BEGIN TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
INSERT INTO "alembic_version" VALUES('0002_add_rooms_owner_id');
CREATE TABLE issues (
	id VARCHAR(36) NOT NULL, 
	room_id VARCHAR(36) NOT NULL, 
	title VARCHAR(500) NOT NULL, 
	description VARCHAR NOT NULL, 
	link VARCHAR(2048) NOT NULL, 
	position INTEGER NOT NULL, 
	estimate VARCHAR(64), 
	archived_at DATETIME, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(room_id) REFERENCES rooms (id) ON DELETE CASCADE
);
INSERT INTO "issues" VALUES('44444444-4444-4444-8444-444444444444','11111111-1111-4111-8111-111111111111','Persisted issue','','',1,NULL,NULL,'2025-01-02 03:04:05.000000');
CREATE TABLE participants (
	id VARCHAR(36) NOT NULL, 
	room_id VARCHAR(36) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	token VARCHAR(255) NOT NULL, 
	is_spectator BOOLEAN NOT NULL, 
	last_seen_at DATETIME NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(room_id) REFERENCES rooms (id) ON DELETE CASCADE, 
	UNIQUE (token)
);
INSERT INTO "participants" VALUES('22222222-2222-4222-8222-222222222222','11111111-1111-4111-8111-111111111111','Owner','legacy-owner-token',0,'2025-01-02 03:04:05.000000','2025-01-02 03:04:05.000000');
INSERT INTO "participants" VALUES('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','Persisted member','legacy-member-token',0,'2025-01-02 03:04:06.000000','2025-01-02 03:04:06.000000');
CREATE TABLE rooms (
	id VARCHAR(36) NOT NULL, 
	code VARCHAR(16) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	host_token VARCHAR(255) NOT NULL, 
	card_set JSON NOT NULL, 
	revealed BOOLEAN NOT NULL, 
	active_issue_id VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, owner_id VARCHAR(36), 
	PRIMARY KEY (id), 
	UNIQUE (host_token)
);
INSERT INTO "rooms" VALUES('11111111-1111-4111-8111-111111111111','LEGACY','Cross-version','legacy-host-token','["0", "1", "2", "3", "5", "8", "13", "21", "?", "Coffee"]',0,'44444444-4444-4444-8444-444444444444','2025-01-02 03:04:05.000000','2025-01-02 03:04:05.000000','22222222-2222-4222-8222-222222222222');
CREATE TABLE votes (
	id VARCHAR(36) NOT NULL, 
	room_id VARCHAR(36) NOT NULL, 
	issue_id VARCHAR(36) NOT NULL, 
	participant_id VARCHAR(36) NOT NULL, 
	value VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(issue_id) REFERENCES issues (id) ON DELETE CASCADE, 
	FOREIGN KEY(participant_id) REFERENCES participants (id) ON DELETE CASCADE, 
	FOREIGN KEY(room_id) REFERENCES rooms (id) ON DELETE CASCADE, 
	CONSTRAINT uq_votes_issue_participant UNIQUE (issue_id, participant_id)
);
INSERT INTO "votes" VALUES('55555555-5555-4555-8555-555555555555','11111111-1111-4111-8111-111111111111','44444444-4444-4444-8444-444444444444','33333333-3333-4333-8333-333333333333','13','2025-01-02 03:04:07.000000','2025-01-02 03:04:07.000000');
CREATE UNIQUE INDEX ix_rooms_code ON rooms (code);
CREATE INDEX issues_room_id_position_idx ON issues (room_id, position);
CREATE INDEX participants_room_id_idx ON participants (room_id);
CREATE INDEX votes_room_id_idx ON votes (room_id);
COMMIT;
